def max_matching(adjl, left, right):
    match_r = [0] * (right + 1)
    match_l = [0] * (left + 1)
    size = 0
    for u in range(1, left + 1):
        parent = {}
        queue = [u]
        found = 0
        for x in queue:
            for r in adjl[x]:
                if r in parent:
                    continue
                parent[r] = x
                if match_r[r] == 0:
                    found = r
                    break
                queue.append(match_r[r])
            if found:
                break
        if found:
            r = found
            while True:
                x = parent[r]
                prev = match_l[x]
                match_l[x] = r
                match_r[r] = x
                if x == u:
                    break
                r = prev
            size += 1
    return size

