#include <iostream>
#include <vector>
#include <string>
using namespace std;

int maxMatching(const vector<vector<int>>& adjl, int left, int right) {
    vector<int> matchR(right + 1, 0), matchL(left + 1, 0);
    int size = 0;
    for (int u = 1; u <= left; u++) {
        vector<int> parent(right + 1, 0);
        vector<int> queue = {u};
        int found = 0;
        for (size_t i = 0; i < queue.size() && !found; i++) {
            int x = queue[i];
            for (int r : adjl[x]) {
                if (parent[r]) continue;
                parent[r] = x;
                if (matchR[r] == 0) {
                    found = r;
                    break;
                }
                queue.push_back(matchR[r]);
            }
        }
        if (found) {
            int r = found;
            for (;;) {
                int x = parent[r];
                int prev = matchL[x];
                matchL[x] = r;
                matchR[r] = x;
                if (x == u) break;
                r = prev;
            }
            size++;
        }
    }
    return size;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long l;
    long long r;
    long long m;
    cin >> l >> r >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<int>> adjl(l + 1);
    for (const vector<long long>& e : edges) adjl[e[0]].push_back((int)e[1]);
    cout << maxMatching(adjl, (int)l, (int)r) << "\n";

    return 0;
}

