import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int maxMatching(long[][] edges, int left, int right) {
        int[] head = new int[left + 2];
        for (int i = 0; i < edges.length; i++) head[(int) edges[i][0] + 1]++;
        for (int u = 1; u <= left; u++) head[u + 1] += head[u];
        int[] to = new int[edges.length];
        int[] fill = new int[left + 2];
        for (int i = 0; i < edges.length; i++) {
            int a = (int) edges[i][0];
            to[head[a] + fill[a]] = (int) edges[i][1];
            fill[a]++;
        }
        int[] matchR = new int[right + 1];
        int[] matchL = new int[left + 1];
        int[] parent = new int[right + 1];
        int[] queue = new int[left + 2];
        int size = 0;
        for (int u = 1; u <= left; u++) {
            Arrays.fill(parent, 0);
            int qh = 0, qt = 0;
            queue[qt++] = u;
            int found = 0;
            while (qh < qt && found == 0) {
                int x = queue[qh++];
                for (int k = head[x]; k < head[x + 1]; k++) {
                    int r = to[k];
                    if (parent[r] != 0) continue;
                    parent[r] = x;
                    if (matchR[r] == 0) {
                        found = r;
                        break;
                    }
                    queue[qt++] = matchR[r];
                }
            }
            if (found != 0) {
                int r = found;
                for (;;) {
                    int x = parent[r];
                    int prev = matchL[x];
                    matchL[x] = r;
                    matchR[r] = x;
                    if (x == u) break;
                    r = prev;
                }
                size++;
            }
        }
        return size;
    }

    public static void main(String[] args) throws IOException {
        long l = Long.parseLong(next());
        long r = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] edges = new long[(int) m][2];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int left = (int) l, right = (int) r;
        System.out.println(maxMatching(edges, left, right));
    }
}
